ui.css:
.hud-panel { background: #ffe23a; border: 3px solid #1b1620; border-radius: 0; box-shadow: 5px 5px 0 #1b1620; padding: 4px 18px 5px; transform: rotate(-1deg); font-family: 'Bangers', Impact, sans-serif; font-size: 38px; letter-spacing: 2px; color: #1b1620; text-shadow: 2px 2px 0 #e8262c; }
.hp-bar { width: 250px; height: 28px; background: radial-gradient(circle, rgba(27,22,32,.22) 1.1px, transparent 1.6px) 0 0/6px 6px, #f4ecd4; border: 3px solid #1b1620; border-radius: 0; box-shadow: 4px 4px 0 #1b1620; transform: skewX(-10deg); overflow: hidden; }
.hp-fill { height: 100%; background: radial-gradient(circle, #8a0c22 1.8px, transparent 2.3px) 0 0/6px 6px, #e8262c; border-right: 3px solid #1b1620; }
.xp-fill { height: 100%; background: radial-gradient(circle, #1474b8 1.7px, transparent 2.2px) 0 0/6px 6px, #2ec4ef; border-right: 3px solid #1b1620; }
.card { background: #fbf5e2; border: 4px solid #1b1620; box-shadow: 8px 8px 0 #1b1620; transform: rotate(-1.5deg); }
